"use client";
import { createContext, useContext, type ReactNode } from "react";
export type WindowPlatform = "windows" | "macos" | "linux";
export interface WindowState {
  maximized: boolean;
  focused: boolean;
}
export interface WindowHost {
  state: WindowState;
  capabilities: {
    minimize: boolean;
    maximize: boolean;
    close: boolean;
    move: boolean;
  };
  minimize(): void | Promise<void>;
  toggleMaximize(): void | Promise<void>;
  close(): void | Promise<void>;
  startDragging?(): void | Promise<void>;
}
const Context = createContext<{
  host: WindowHost;
  onError: (error: unknown) => void;
} | null>(null);
export function WindowHostProvider({
  host,
  onError,
  children,
}: {
  host: WindowHost;
  onError: (error: unknown) => void;
  children: ReactNode;
}) {
  return (
    <Context.Provider value={{ host, onError }}>{children}</Context.Provider>
  );
}
export function useWindowHost() {
  const value = useContext(Context);
  if (!value) throw new Error("Wrap window components in WindowHostProvider.");
  return value.host;
}
export function useWindowAction() {
  const value = useContext(Context);
  if (!value) throw new Error("Wrap window components in WindowHostProvider.");
  return (action: () => void | Promise<void>) => {
    try {
      Promise.resolve(action()).catch(value.onError);
    } catch (error) {
      value.onError(error);
    }
  };
}

"use client";
import { Minus, Square, Copy, X } from "lucide-react";
import type { CSSProperties } from "react";
import { cn } from "@/lib/utils";
import {
  useWindowHost,
  useWindowAction,
  type WindowPlatform,
} from "./window-host";
export function WindowControls({
  platform = "windows",
  className,
}: {
  platform?: WindowPlatform;
  className?: string;
}) {
  const host = useWindowHost();
  const run = useWindowAction();
  const mac = platform === "macos";
  const controls = [
    {
      name: "Minimize window",
      icon: Minus,
      action: () => host.minimize(),
      enabled: host.capabilities.minimize,
      color: "bg-amber-400",
    },
    {
      name: host.state.maximized ? "Restore window" : "Maximize window",
      icon: host.state.maximized ? Copy : Square,
      action: () => host.toggleMaximize(),
      enabled: host.capabilities.maximize,
      color: "bg-green-500",
    },
    {
      name: "Close window",
      icon: X,
      action: () => host.close(),
      enabled: host.capabilities.close,
      color: "bg-red-400",
    },
  ];
  const ordered = mac ? [controls[2], controls[0], controls[1]] : controls;
  return (
    <div
      data-runic-no-drag
      style={{ "--webui-app-region": "no-drag" } as CSSProperties}
      className={cn(
        "flex shrink-0 items-center",
        mac && "gap-2 px-4",
        className,
      )}
    >
      {ordered.map(({ name, icon: Icon, action, enabled, color }) => (
        <button
          type="button"
          key={name}
          aria-label={name}
          title={name}
          disabled={!enabled}
          onClick={() => run(action)}
          className={cn(
            "group grid place-items-center outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-30 disabled:pointer-events-none",
            mac
              ? cn(
                  "size-3.5 rounded-full",
                  color,
                  !host.state.focused && "!bg-muted-foreground",
                )
              : "h-11 w-11 text-muted-foreground hover:bg-accent",
            !mac &&
              name === "Close window" &&
              "hover:bg-red-600 hover:text-white",
          )}
        >
          <Icon
            aria-hidden
            className={cn(
              mac
                ? "size-2.5 text-black opacity-0 group-hover:opacity-70 group-focus-visible:opacity-70"
                : "size-3.5",
            )}
          />
        </button>
      ))}
    </div>
  );
}

"use client";
import type { CSSProperties, ReactNode } from "react";
import { cn } from "@/lib/utils";
import {
  useWindowHost,
  useWindowAction,
  type WindowPlatform,
} from "./window-host";
import { WindowControls } from "./window-controls";
export function TitleBar({
  title,
  icon,
  actions,
  platform = "windows",
  className,
}: {
  title: ReactNode;
  icon?: ReactNode;
  actions?: ReactNode;
  platform?: WindowPlatform;
  className?: string;
}) {
  const host = useWindowHost();
  const run = useWindowAction();
  return (
    <header
      className={cn(
        "flex h-11 shrink-0 select-none items-center border-b border-border bg-muted/30",
        !host.state.focused && "opacity-65",
        className,
      )}
    >
      {platform === "macos" && <WindowControls platform={platform} />}
      <div
        data-runic-drag-region
        style={
          {
            "--webui-app-region": host.capabilities.move ? "drag" : "no-drag",
            touchAction: "none",
          } as CSSProperties
        }
        className="flex h-full min-w-0 flex-1 items-center gap-2.5 px-4 text-xs text-muted-foreground"
        onPointerDown={(event) => {
          if (
            event.button === 0 &&
            event.detail !== 2 &&
            host.capabilities.move &&
            host.startDragging
          )
            run(() => host.startDragging!());
        }}
        onDoubleClick={() => {
          if (host.capabilities.maximize) run(() => host.toggleMaximize());
        }}
      >
        {icon}
        <span className="truncate">{title}</span>
      </div>
      {actions && (
        <div
          data-runic-no-drag
          style={{ "--webui-app-region": "no-drag" } as CSSProperties}
          className="flex items-center gap-1 px-2"
        >
          {actions}
        </div>
      )}
      {platform !== "macos" && <WindowControls platform={platform} />}
    </header>
  );
}

"use client";
import { useId, useRef, type ReactNode } from "react";
import { X, Plus } from "lucide-react";
import { cn } from "@/lib/utils";
export interface DocumentTab {
  id: string;
  title: string;
  dirty?: boolean;
  icon?: ReactNode;
}
export function DocumentTabs({
  tabs,
  value,
  onValueChange,
  onClose,
  onAdd,
  children,
  className,
}: {
  tabs: DocumentTab[];
  value: string;
  onValueChange: (id: string) => void;
  onClose?: (id: string) => void;
  onAdd?: () => void;
  children: ReactNode;
  className?: string;
}) {
  const prefix = useId();
  const refs = useRef(new Map<string, HTMLButtonElement>());
  const tabId = (id: string) => prefix + "-tab-" + id;
  const panelId = prefix + "-panel";
  const select = (index: number) => {
    const tab = tabs[index];
    if (tab) {
      onValueChange(tab.id);
      refs.current.get(tab.id)?.focus();
    }
  };
  return (
    <div className={cn("flex min-h-0 flex-1 flex-col", className)}>
      <div className="flex shrink-0 items-center border-b border-border bg-muted/20">
        <div
          role="tablist"
          aria-label="Open documents"
          className="flex min-w-0 flex-1 overflow-x-auto"
        >
          {tabs.map((tab, index) => (
            <div
              key={tab.id}
              className={cn(
                "relative flex shrink-0 items-center border-r border-border",
                value === tab.id &&
                  "bg-background after:absolute after:inset-x-0 after:top-0 after:h-0.5 after:bg-primary",
              )}
            >
              <button
                type="button"
                role="tab"
                id={tabId(tab.id)}
                aria-controls={panelId}
                aria-selected={value === tab.id}
                tabIndex={value === tab.id ? 0 : -1}
                ref={(el) => {
                  if (el) refs.current.set(tab.id, el);
                  else refs.current.delete(tab.id);
                }}
                className="flex h-10 items-center gap-2 pl-4 pr-2 text-xs outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                onClick={() => onValueChange(tab.id)}
                onKeyDown={(e) => {
                  const next =
                    e.key === "ArrowRight"
                      ? (index + 1) % tabs.length
                      : e.key === "ArrowLeft"
                        ? (index - 1 + tabs.length) % tabs.length
                        : e.key === "Home"
                          ? 0
                          : e.key === "End"
                            ? tabs.length - 1
                            : null;
                  if (next !== null) {
                    e.preventDefault();
                    select(next);
                  }
                  if (e.key === "Delete" && onClose) {
                    e.preventDefault();
                    onClose(tab.id);
                  }
                }}
              >
                {tab.icon}
                <span>{tab.title}</span>
                {tab.dirty && (
                  <span
                    className="size-1.5 rounded-full bg-primary"
                    aria-label="Unsaved changes"
                  />
                )}
              </button>
              {onClose && (
                <button
                  type="button"
                  aria-label={"Close " + tab.title}
                  onClick={() => onClose(tab.id)}
                  className="mr-2 grid size-6 place-items-center rounded text-muted-foreground hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring"
                >
                  <X aria-hidden className="size-3" />
                </button>
              )}
            </div>
          ))}
        </div>
        {onAdd && (
          <button
            type="button"
            aria-label="New document"
            onClick={onAdd}
            className="m-1 grid size-8 shrink-0 place-items-center rounded text-muted-foreground hover:bg-accent focus-visible:outline-2 focus-visible:outline-ring"
          >
            <Plus aria-hidden className="size-4" />
          </button>
        )}
      </div>
      <div
        role="tabpanel"
        id={panelId}
        aria-labelledby={
          tabs.some((t) => t.id === value) ? tabId(value) : undefined
        }
        aria-label={tabs.length ? undefined : "No open documents"}
        tabIndex={0}
        className="min-h-0 flex-1 overflow-auto outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
      >
        {children}
      </div>
    </div>
  );
}

"use client";
import { useRef, useState, type ReactNode } from "react";
import { cn } from "@/lib/utils";
export function Workspace({
  sidebar,
  children,
  sidebarLabel = "Sidebar width",
  defaultWidth = 220,
  minWidth = 160,
  maxWidth = 360,
  collapsed = false,
  className,
}: {
  sidebar: ReactNode;
  children: ReactNode;
  sidebarLabel?: string;
  defaultWidth?: number;
  minWidth?: number;
  maxWidth?: number;
  collapsed?: boolean;
  className?: string;
}) {
  const clamp = (n: number) => Math.min(maxWidth, Math.max(minWidth, n));
  const [width, setWidth] = useState(clamp(defaultWidth));
  const start = useRef<{ x: number; width: number } | null>(null);
  return (
    <div className={cn("flex min-h-0 flex-1 overflow-hidden", className)}>
      {!collapsed && (
        <>
          <aside
            style={{ width }}
            className="shrink-0 overflow-auto bg-muted/15"
          >
            {sidebar}
          </aside>
          <div
            role="separator"
            aria-label={sidebarLabel}
            aria-orientation="vertical"
            aria-valuemin={minWidth}
            aria-valuemax={maxWidth}
            aria-valuenow={width}
            tabIndex={0}
            className="relative z-10 w-1 shrink-0 cursor-col-resize touch-none bg-border outline-none before:absolute before:inset-y-0 before:-left-1 before:w-3 hover:bg-primary focus-visible:bg-primary"
            onPointerDown={(e) => {
              if (e.button !== 0) return;
              e.currentTarget.setPointerCapture(e.pointerId);
              start.current = { x: e.clientX, width };
            }}
            onPointerMove={(e) => {
              if (start.current)
                setWidth(
                  clamp(start.current.width + e.clientX - start.current.x),
                );
            }}
            onPointerUp={(e) => {
              start.current = null;
              if (e.currentTarget.hasPointerCapture(e.pointerId))
                e.currentTarget.releasePointerCapture(e.pointerId);
            }}
            onPointerCancel={() => {
              start.current = null;
            }}
            onLostPointerCapture={() => {
              start.current = null;
            }}
            onDoubleClick={() => setWidth(clamp(defaultWidth))}
            onKeyDown={(e) => {
              if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) {
                e.preventDefault();
                setWidth((w) =>
                  e.key === "Home"
                    ? minWidth
                    : e.key === "End"
                      ? maxWidth
                      : clamp(
                          w +
                            (e.key === "ArrowRight" ? 1 : -1) *
                              (e.shiftKey ? 32 : 8),
                        ),
                );
              }
            }}
          />
        </>
      )}
      <div className="flex min-w-0 flex-1 flex-col">{children}</div>
    </div>
  );
}

import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";
export function StatusBar({ className, ...props }: ComponentProps<"footer">) {
  return (
    <footer
      aria-label="Application status"
      className={cn(
        "flex h-8 shrink-0 items-center justify-between gap-3 border-t border-border bg-muted/30 px-3 text-[11px] text-muted-foreground",
        className,
      )}
      {...props}
    />
  );
}
export function StatusBarItem({ className, ...props }: ComponentProps<"span">) {
  return (
    <span
      className={cn("inline-flex items-center gap-1.5", className)}
      {...props}
    />
  );
}

import type { WindowHost, WindowState } from "./window-host";
/** Structural subset of an application-generated Runic Views client. */
export interface RunicWindowCommands {
  minimize(): Promise<unknown>;
  toggleMaximized(): Promise<unknown>;
  requestClose(): Promise<unknown>;
}
export interface RunicWindowSnapshot extends WindowState {
  canMinimize: boolean;
  canToggleMaximized: boolean;
  canRequestClose: boolean;
  canMove: boolean;
}
/** Recreate from useView's current snapshot. Commands remain owned by useView. */
export function createRunicWindowHost(
  client: RunicWindowCommands,
  state: RunicWindowSnapshot,
): WindowHost {
  return {
    state,
    capabilities: {
      minimize: state.canMinimize,
      maximize: state.canToggleMaximized,
      close: state.canRequestClose,
      move: state.canMove,
    },
    minimize: async () => {
      await client.minimize();
    },
    toggleMaximize: async () => {
      await client.toggleMaximized();
    },
    close: async () => {
      await client.requestClose();
    },
    // Runic Desktop's authenticated bootstrap owns --webui-app-region dragging.
  };
}
